// Checks one module of src/. Usage: node check.mjs <name>
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const checks = {
  discount: {
    file: 'src/discount.js',
    name: 'applyDiscount',
    ok: [[[10000, 15], 8500], [[2000, 50], 1000], [[0, 30], 0], [[10000, 0], 10000]],
    bad: [[10000, 150], [10000, -5]],
  },
  tax: {
    file: 'src/tax.js',
    name: 'addTax',
    ok: [[[10000, 7], 10700], [[2000, 25], 2500], [[0, 7], 0]],
    bad: [[-1, 7]],
  },
  fee: {
    file: 'src/fee.js',
    name: 'cardFee',
    ok: [[[10000], 320], [[1000], 59], [[2000], 88]],
    bad: [[10.5]],
  },
  interest: {
    file: 'src/interest.js',
    name: 'simpleInterest',
    ok: [[[120000, 5, 12], 6000], [[120000, 10, 6], 6000], [[0, 5, 3], 0]],
    bad: [[120000, 5, -1]],
  },
};

function fail(message) {
  console.error(message);
  process.exit(1);
}

const key = process.argv[2];
const check = checks[key];
if (!check) fail(`unknown check: ${key}`);
const loaded = await import(pathToFileURL(resolve(check.file)).href);
const fn = loaded[check.name];
if (typeof fn !== 'function') fail(`${check.file} does not export ${check.name}`);
for (const [args, want] of check.ok) {
  const got = fn(...args);
  if (got !== want) fail(`${check.name}(${args.join(', ')}) gave ${got}, want ${want}`);
}
for (const args of check.bad) {
  let threw = false;
  try {
    fn(...args);
  } catch {
    threw = true;
  }
  if (!threw) fail(`${check.name}(${args.join(', ')}) did not throw`);
}
console.log(`${key}: ok`);

// Money helpers. Amounts are integer cents.

const EPSILON = 1e-9;

export function roundHalfEven(value) {
  const floor = Math.floor(value);
  const rest = value - floor;
  if (rest > 0.5 + EPSILON) return floor + 1;
  if (rest < 0.5 - EPSILON) return floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

// Errors of the ledger library.

export class LedgerError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'LedgerError';
    this.code = code;
  }
}

