import { roundHalfEven } from './money.js';
import { LedgerError } from './errors.js';

export function applyDiscount(amountCents, percent) {
  if (percent < 0 || percent > 100) {
    throw new LedgerError('PERCENT_OUT_OF_RANGE', `percent ${percent} is outside 0 to 100`);
  }
  return roundHalfEven((amountCents * (100 - percent)) / 100);
}

// owner: ledger-team
import { roundHalfEven } from './money.js';
import { LedgerError } from './errors.js';

export function addTax(netCents, ratePercent) {
  if (netCents < 0) {
    throw new LedgerError('NEGATIVE_AMOUNT', 'the net amount is negative');
  }
  return netCents + roundHalfEven((netCents * ratePercent) / 100);
}

// owner: ledger-team
import { roundHalfEven } from './money.js';
import { LedgerError } from './errors.js';

export function cardFee(amountCents) {
  if (!Number.isInteger(amountCents)) {
    throw new LedgerError('NOT_WHOLE_CENTS', 'the amount is not a whole number of cents');
  }
  return roundHalfEven((amountCents * 29) / 1000) + 30;
}

// owner: ledger-team
import { roundHalfEven } from './money.js';
import { LedgerError } from './errors.js';

export function simpleInterest(balanceCents, annualPercent, months) {
  if (months < 0) {
    throw new LedgerError('NEGATIVE_MONTHS', 'the number of months is negative');
  }
  return roundHalfEven((balanceCents * annualPercent * months) / 1200);
}
